REGION = {  # model region -> the countries averaged (the largest economies of the composites; HK and Taiwan have no UN vote)
 "eu27": ["DEU", "FRA", "ITA", "ESP", "POL"], "us": ["USA"], "china": ["CHN"], "japan": ["JPN"], "korea": ["KOR"], "india": ["IND"],
 "indonesia": ["IDN"], "russia": ["RUS"], "uk": ["GBR"], "brasil": ["BRA"], "argentina": ["ARG"], "bolivia": ["BOL"], "canada": ["CAN"],
 "colombia": ["COL"], "drc": ["COD"], "ghana": ["GHA"], "ivorycoast": ["CIV"], "madagascar": ["MDG"], "malasya": ["MYS"], "mexico": ["MEX"],
 "mozambique": ["MOZ"], "myanmar": ["MMR"], "newzealand": ["NZL"], "nigeria": ["NGA"], "paraguay": ["PRY"], "peru": ["PER"], "uruguay": ["URY"],
 "venezuela": ["VEN"], "angola": ["AGO"], "efta": ["CHE", "NOR"], "oceania": ["AUS"], "eastasia": ["MNG"], "safr": ["ZAF", "ZMB"],
 "latinamer": ["CHL", "ECU", "GTM"], "mena": ["SAU", "TUR", "IRN", "ARE"], "nafr": ["EGY", "MAR", "DZA"], "restofworld": ["KAZ", "UKR"],
 "seasia": ["THA", "VNM", "PHL"], "southasia": ["PAK", "BGD"], "wafr": ["SEN", "MLI", "GIN"], "cafr": ["CMR", "GAB"], "eafr": ["KEN", "ETH", "TZA"]}
x = {reg: statistics.mean(statistics.mean(IP[c]) for c in cs) for reg, cs in REGION.items()}
x_eu = x["eu27"]
s = {reg: max(0.0, x_eu - v) for reg, v in x.items()}
s_med = statistics.median(v for reg, v in s.items() if reg != "eu27")
g = {reg: 0.5 + v / (2 * s_med) for reg, v in s.items()}
if __name__ == "__main__":
    print(f"EU ideal point {x_eu:.2f}; median one-sided distance {s_med:.2f}")
    for reg in sorted(x, key=lambda r: -x[r]):
        print(f"{reg:12s} x {x[reg]:6.2f}  s {s[reg]:5.2f}  g {g[reg]:5.2f}")
    json.dump({"x": x, "s": s, "g": g, "s_med": s_med, "x_eu": x_eu}, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "geo_schedule.json"), "w"), indent=1)
